#!/bin/sh
# Internal job launcher. Names are generated by the worker, never user tags/paths.
set -eu
id=${1:-}
case "$id" in *[!a-f0-9]*|'') exit 1 ;; esac
[ "${#id}" = 32 ] || exit 1
base=/tmp/mb-runtime/jobs/$id
CG=/sys/fs/cgroup/monkey-business-engines/job-$id
[ -d "$CG" ] && [ ! -L "$CG" ] || exit 1
export MB_ENGINE_JOINED=1
case "${2:-}" in
 xray) printf '%s\n' "$$" > "$CG/cgroup.procs"
  exec /usr/share/monkey-business/engine-run.sh /usr/bin/xray run -c "$base/xray.json" >/dev/null 2>&1 ;;
 hysteria)
  index=${3:-}
  case "$index" in *[!0-9]*|'') exit 1 ;; esac
  [ "$index" -lt 200 ] || exit 1
  CG="$CG/node-$index"
  [ -d "$CG" ] && [ ! -L "$CG" ] || exit 1
  printf '%s\n' "$$" > "$CG/cgroup.procs"
  exec /usr/share/monkey-business/engine-run.sh /usr/bin/hysteria client -c "$base/hy-$index.json" >/dev/null 2>&1
  ;;
 *) exit 1 ;;
esac
